package ru.murad.yourmarket.service.impl;
import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import ru.murad.yourmarket.dto.response.AdvertisementResponseDto;import ru.murad.yourmarket.exception.*;import ru.murad.yourmarket.mapper.AdvertisementMapper;import ru.murad.yourmarket.model.enums.AdvertisementStatus;import ru.murad.yourmarket.repository.AdvertisementRepository;import ru.murad.yourmarket.service.*;import java.util.*;
@Slf4j @Service @RequiredArgsConstructor public class AdvertisementServiceImpl implements AdvertisementService {private final AdvertisementRepository repository;private final AdvertisementMapper mapper;private final ChannelMessageDeletionService deletion;private final AdvertisementLifecycleTransactionService lifecycle;
@Override @Transactional(readOnly=true) public List<AdvertisementResponseDto> findRecentForUser(Long user){return repository.findByTelegramUserIdOrderByCreatedAtDesc(user,PageRequest.of(0,10)).stream().map(mapper::toResponse).toList();}
@Override public AdvertisementResponseDto deletePublished(UUID id,Long user){var ad=lifecycle.authorizeDeletion(id,user);if(ad.getStatus()==AdvertisementStatus.DELETED)return mapper.toResponse(ad);if(!deletion.deleteAll(id))throw new TelegramPublicationException("Не все сообщения удалось удалить",null);log.info("Объявление снято advertisementId={}, telegramUserId={}",id,user);return lifecycle.finishDeletion(id);}
@Override @Transactional(readOnly=true) public AdvertisementResponseDto findById(UUID id){return mapper.toResponse(repository.findById(id).orElseThrow(AdvertisementNotFoundException::new));}}
